import { MapContainer, TileLayer, Polyline, Marker } from "react-leaflet";
import { useEffect, useState } from "react";
import axios from "axios";
import L from "leaflet";

// 🔥 Fix marker icon issue
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl:
    "https://unpkg.com/leaflet@1.7.1/dist/images/marker-icon-2x.png",
  iconUrl:
    "https://unpkg.com/leaflet@1.7.1/dist/images/marker-icon.png",
  shadowUrl:
    "https://unpkg.com/leaflet@1.7.1/dist/images/marker-shadow.png",
});

function App() {
  const [path, setPath] = useState([]);
  const [latest, setLatest] = useState(null);

  useEffect(() => {
    fetchData();
    const interval = setInterval(fetchData, 3000);
    return () => clearInterval(interval);
  }, []);

  const fetchData = async () => {
    try {
      const res = await axios.get("http://localhost:3000/path");
      const latestRes = await axios.get("http://localhost:3000/latest");

      const coords = res.data
        .filter(d => d.location && d.location.coordinates[0] !== 0)
        .map(d => [
          d.location.coordinates[1],
          d.location.coordinates[0],
        ]);

      setPath(coords);
      setLatest(latestRes.data);
    } catch (err) {
      console.error("Error fetching data:", err);
    }
  };

  return (
    <div className="dashboard">
      <h2>🚁 Drone Live Map</h2>

      {latest && (
        <div className="metrics">
          <p>Altitude: {latest.alt}</p>
          <p>Voltage: {latest.voltage}</p>
          <p>Satellites: {latest.sats}</p>
        </div>
      )}

      <MapContainer
        center={[12.9716, 77.5946]}
        zoom={18}
        style={{ height: "500px", width: "100%" }}
      >
        <TileLayer
          attribution="&copy; OpenStreetMap contributors"
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />

        <Polyline positions={path} />

        {latest && latest.location && (
          <Marker
            position={[
              latest.location.coordinates[1],
              latest.location.coordinates[0],
            ]}
          />
        )}
      </MapContainer>
    </div>
  );
}

export default App;
